// CrushFling Auto Register — standalone Windows desktop app.
//
// This file is generated by scripts/build-crushfling-standalone.cjs from
// scripts/standalone/main.go.tmpl. Edit the template, not the generated copy.
package main

import (
	"embed"
	"io/fs"
	"log"
	"os"
	"path/filepath"

	"crushfling/internal/crushfling"

	"github.com/wailsapp/wails/v2"
	"github.com/wailsapp/wails/v2/pkg/options"
	"github.com/wailsapp/wails/v2/pkg/options/assetserver"
	"github.com/wailsapp/wails/v2/pkg/options/windows"
)

//go:embed all:frontend/dist
var embeddedAssets embed.FS

func main() {
	dataDir := resolveDataDir()
	if err := os.MkdirAll(dataDir, 0o755); err != nil {
		log.Fatal(err)
	}
	service, err := crushfling.NewService(filepath.Join(dataDir, "crushfling"))
	if err != nil {
		log.Fatal("crushfling service: ", err)
	}
	app := NewApp(dataDir, service)

	dist, err := fs.Sub(embeddedAssets, "frontend/dist")
	if err != nil {
		log.Fatal(err)
	}

	webviewDir := filepath.Join(dataDir, "webview")
	if err := os.MkdirAll(webviewDir, 0o755); err != nil {
		log.Fatal(err)
	}

	err = wails.Run(&options.App{
		Title:            "CrushFling Auto Register",
		Width:            1240,
		Height:           860,
		MinWidth:         1000,
		MinHeight:        680,
		BackgroundColour: &options.RGBA{R: 22, G: 23, B: 22, A: 255},
		AssetServer:      &assetserver.Options{Assets: dist},
		OnStartup:        app.startup,
		OnShutdown:       app.shutdown,
		Bind:             []interface{}{app},
		Windows: &windows.Options{
			Theme:               windows.SystemDefault,
			WebviewUserDataPath: webviewDir,
		},
	})
	if err != nil {
		log.Fatal(err)
	}
}

// resolveDataDir keeps every setting, account and log next to the exe, so the
// whole folder stays portable (copy it and the data travels with it).
func resolveDataDir() string {
	exe, err := os.Executable()
	if err != nil {
		wd, _ := os.Getwd()
		return filepath.Join(wd, "data")
	}
	return filepath.Join(filepath.Dir(exe), "data")
}
